-- 00_insert_missing_partners.sql
-- Pre-passo da correcao dos snapshots de 2026-08-14.
-- Cadastra os parceiros presentes na planilha (aba 'Extração  - Base final diagnóst') que ainda NAO existem
-- em `partners`, para que o INSERT de snapshots do 02_apply.sql (que faz JOIN partners)
-- nao descarte nenhuma linha.

-- Fonte: aba 'Extração  - Base final diagnóst' (fresh, visivel) do arquivo 6ce0d2f5-13_08_2026_2.xlsx
-- Mesmo parsing de src/lib/import/parsePartners.ts + objeto de upsert de src/pages/Importacao.tsx.
--   Dedup por coluna A (accountancy_id), mantendo a PRIMEIRA ocorrencia; ID como string integer (sem '.0').
--   Normalizacao numerica identica (parseNumber, parseNullableNumber, parseDecimalPercent;
--   regra de percentual: 0 < v <= 15 => round(v*100); senao round(v); Math.round = half-up).
--   fila: 'RETENÇÃO' se AX for RETENÇÃO/RETENCAO, senao 'EXPANSÃO'.
--   usa_capro: BC == 'sim' (case-insensitive) => true, senao false.
-- Linhas na staging: 3959 (todos os parceiros da aba; ON CONFLICT cuida dos que ja existem).
-- Confere: SUM(licencas)=58052, SUM(licencas_engajadas)=41356.

-- IMPORTANTE: gerente_id NAO esta na staging. No INSERT final ele entra como NULL para os
-- parceiros novos (fiel ao app, que so preserva gerente_id de parceiros ja existentes via
-- gerenteMap; parceiro novo => null). O texto `gerente` (coluna C = owner_name) e populado,
-- porque os dashboards filtram parceiros por esse texto.
-- last_imported_at usa o valor fixo historico '2026-08-14 12:00:00-03' (nao now()).

-- Este script NAO escreve na tabela real ate o bloco BEGIN...COMMIT no fim (COMMIT comentado).

-- 1) Staging (colunas de partners que vamos inserir; gerente_id fica de fora -> NULL no insert)
CREATE TABLE IF NOT EXISTS stg_partners_20260814 (
  accountancy_id text,
  nome text,
  gerente text,
  nivel text,
  perfil_parceiro text,
  perfil_servico text,
  fila text,
  faixa_engajamento text,
  licencas numeric,
  licencas_engajadas numeric,
  estoque numeric,
  percentual_engajamento numeric,
  penetracao numeric,
  exportacoes_90d numeric,
  cnpjs numeric,
  cnpjs_livres numeric,
  contas_potencial numeric,
  ratio numeric,
  segmento text,
  atribuidas numeric,
  percentual_atribuidas numeric,
  usa_capro boolean
);

TRUNCATE stg_partners_20260814;

-- 2) Carga das 3959 linhas da aba 'Extração  - Base final diagnóst' (chunks de ~500)









-- Confere a carga da staging (esperado: linhas=3959, soma_licencas=58052, soma_engajadas=41356)
SELECT count(*) AS linhas, sum(licencas) AS soma_licencas, sum(licencas_engajadas) AS soma_engajadas
FROM stg_partners_20260814;

-- 3) Preview: quantos da staging NAO existem em partners. NAO escreve nada ainda.
SELECT count(*) AS faltando
FROM stg_partners_20260814 s
LEFT JOIN partners p ON trim(p.accountancy_id::text) = trim(s.accountancy_id)
WHERE p.id IS NULL;

-- Lista os parceiros faltantes (candidatos ao insert), maiores primeiro:
SELECT s.accountancy_id, s.nome, s.gerente, s.licencas
FROM stg_partners_20260814 s
LEFT JOIN partners p ON trim(p.accountancy_id::text) = trim(s.accountancy_id)
WHERE p.id IS NULL
ORDER BY s.licencas DESC;

-- 4) Mutacao (revisavel e gated). So insere os que faltam; ON CONFLICT protege os existentes.
BEGIN;

SELECT count(*) AS partners_antes FROM partners;

  accountancy_id, nome, gerente, gerente_id, nivel, perfil_parceiro, perfil_servico, fila,
  faixa_engajamento, licencas, licencas_engajadas, estoque, percentual_engajamento, penetracao,
  exportacoes_90d, cnpjs, cnpjs_livres, contas_potencial, ratio, segmento, atribuidas,
  percentual_atribuidas, usa_capro, last_imported_at
)
SELECT
  s.accountancy_id, s.nome, s.gerente, NULL::uuid AS gerente_id, s.nivel, s.perfil_parceiro,
  s.perfil_servico, s.fila, s.faixa_engajamento, s.licencas, s.licencas_engajadas, s.estoque,
  s.percentual_engajamento, s.penetracao, s.exportacoes_90d, s.cnpjs, s.cnpjs_livres,
  s.contas_potencial, s.ratio, s.segmento, s.atribuidas, s.percentual_atribuidas, s.usa_capro,
  timestamptz '2026-08-14 12:00:00-03' AS last_imported_at
FROM stg_partners_20260814 s
ON CONFLICT (accountancy_id) DO NOTHING;

SELECT count(*) AS partners_depois FROM partners;
-- partners_depois - partners_antes DEVE ser o numero de faltantes listado no preview.

-- Re-check do snapshot: apos o insert, quantos snapshots ficam sem parceiro correspondente.
-- (Requer que o 01_stage_and_preview.sql ja tenha criado stg_snapshot_20260814 nesta sessao;
--  ver ordem de execucao no README. Esperado agora: 0.)
SELECT count(*) AS snapshot_unmatched_agora
FROM stg_snapshot_20260814 s
LEFT JOIN partners p ON trim(p.accountancy_id::text) = trim(s.accountancy_id)
WHERE p.id IS NULL;

-- Revise: inseridos (partners_depois - partners_antes) = faltantes do preview e snapshot_unmatched_agora = 0.
-- Se estiver certo: COMMIT;  senao: ROLLBACK;
-- COMMIT;
-- ROLLBACK;
